/**
 * MoviePilot 通知（单节点）
 *
 * 统一处理 MoviePilot 的所有通知类型：
 *   - 订阅：subscribe.added / subscribe.complete / subscribe.modified / subscribe.deleted
 *   - 下载/入库：download.added / transfer.complete（入库额外输出 transfer 元数据供聚合）
 *   - 插件：plugin.triggered（刷流等）
 *   - 站内通知：notice.message（刷流、体育、站点私信、通用）
 *
 * 只处理 mp-* 来源，其它来源直接返回空数组，交给别的节点。
 */

// ======================= 可配置图标与链接 =======================
// MoviePilot 默认图标（所有 MP 通知在匹配不到媒体/站点图标时的统一兜底）
const MP_DEFAULT_ICON = ""; // 可选：MoviePilot 默认兜底图标 URL（留空则使用 Bark 默认图标）
// 体育赛事通知（AutoSports 插件）图标
const SPORTS_ICON = ""; // 可选：体育赛事通知图标 URL
// PT 站点图标映射（[站点关键词, 图标网址]，不区分大小写；未命中自动用 MP_DEFAULT_ICON）
const SITE_ICONS = [
  // 可选：按站点关键词匹配专属图标（从上到下依次包含匹配），例如：
  // ["站点关键词", "https://your-image-host.example.com/icons/site.png"]
];
// MoviePilot 与 Jellyfin 跳转地址
const MP_BASE_URL = "https://your-moviepilot.example.com"; // 修改为你的 MoviePilot 访问地址
const JELLYFIN_MOVIES = "https://your-jellyfin.example.com/web/#/movies.html?topParentId=YOUR_MOVIES_LIBRARY_ID&collectionType=movies"; // 可选：修改为你的 Jellyfin 电影库地址
const JELLYFIN_TV = "https://your-jellyfin.example.com/web/#/tv.html?topParentId=YOUR_TV_LIBRARY_ID&collectionType=tvshows"; // 可选：修改为你的 Jellyfin 剧集库地址
const JELLYFIN_SPORTS = "https://your-jellyfin.example.com/web/#/list?parentId=YOUR_SPORTS_LIBRARY_ID&serverId=YOUR_JELLYFIN_SERVER_ID"; // 可选：修改为你的 Jellyfin 体育库地址
// ===============================================================

let testMode = false;

const str = (v) => (v === null || v === undefined ? "" : String(v));
const num = (v) => {
    const n = Number(v);
    return Number.isFinite(n) ? n : 0;
};
const round = (v, digits = 2) => {
    const n = Number(v);
    if (!Number.isFinite(n)) return "";
    const factor = Math.pow(10, digits);
    return Math.round(n * factor) / factor;
};
const formatSize = (value) => {
    const n = num(value);
    if (n / 1000000000000 >= 1) return `${round(n / 1000000000000, 2)} TB`;
    if (n / 1000000000 >= 1) return `${round(n / 1000000000, 2)} GB`;
    return `${round(n / 1000000, 2)} MB`;
};
const lines = (v) => str(v).split("\n");
const after = (v, sep) => {
    const s = str(v);
    if (!sep) return s;
    const i = s.indexOf(sep);
    return i === -1 ? s : s.slice(i + sep.length);
};
const utf8Bytes = (ch) => {
    const cp = ch.codePointAt(0);
    if (cp <= 0x7f) return 1;
    if (cp <= 0x7ff) return 2;
    if (cp <= 0xffff) return 3;
    return 4;
};
const clipUtf8 = (text, maxBytes, suffix = "") => {
    const s = str(text);
    let total = 0;
    for (const ch of s) total += utf8Bytes(ch);
    if (total <= maxBytes) return s;
    let suffixBytes = 0;
    for (const ch of suffix) suffixBytes += utf8Bytes(ch);
    const limit = Math.max(0, maxBytes - suffixBytes);
    let used = 0;
    let out = "";
    for (const ch of s) {
        const b = utf8Bytes(ch);
        if (used + b > limit) break;
        out += ch;
        used += b;
    }
    return out.trimEnd() + suffix;
};
const bark = (group, title, body, extra = {}) => {
    const fullTitle = clipUtf8(testMode ? `【🧪测试】 ${title}` : title, 240, "…");
    const safeBody = clipUtf8(body, 2800, "\n…（内容过长已截断）");
    const payload = { group, title: fullTitle, body: safeBody, action: "none" };
    for (const [key, value] of Object.entries(extra)) {
        if (value !== undefined && value !== null && value !== "") payload[key] = value;
    }
    if (!payload.icon) payload.icon = MP_DEFAULT_ICON;
    return payload;
};
const fail = (reason, source) => [{ json: { unmatched: true, reason, source } }];

// 统一展示格式：空值统一用 —，评分保留一位小数，时长省略为 0 的单位
const DASH = "—";
const val = (value) => {
    const s = str(value).trim();
    return s || DASH;
};
const score = (value) => {
    const raw = str(value).trim();
    if (!raw) return DASH;
    const n = Number(raw);
    return Number.isFinite(n) ? n.toFixed(1) : raw;
};
const durationText = (hours, minutes) => {
    const h = Math.floor(num(hours));
    const m = Math.round(num(minutes));
    if (h && m) return `${h} 小时 ${m} 分钟`;
    if (h) return `${h} 小时`;
    if (m) return `${m} 分钟`;
    return DASH;
};
const formatMinutes = (minutes) => {
    const total = Math.round(num(minutes));
    if (total <= 0) return DASH;
    return durationText(Math.floor(total / 60), total % 60);
};
// TMDB 的 episode_run_time 是常见单集时长列表（不是总时长）：
// 单值直接展示；多值展示“最短 ~ 最长（平均）”；无数据时保持 —
const mediaDurationText = (mi = {}) => {
    const rawList = Array.isArray(mi.episode_run_time) ? mi.episode_run_time : [];
    const valid = rawList.map(num).filter((v) => v > 0);
    if (valid.length === 1) return formatMinutes(valid[0]);
    if (valid.length > 1) {
        const min = Math.min(...valid);
        const max = Math.max(...valid);
        if (min === max) return formatMinutes(min);
        const avg = Math.round(valid.reduce((a, b) => a + b, 0) / valid.length);
        return `${formatMinutes(min)} ~ ${formatMinutes(max)}（平均 ${formatMinutes(avg)}）`;
    }
    const rt = num(mi.runtime);
    return rt > 0 ? formatMinutes(rt) : DASH;
};
const linkMP = (url) => `🗃️在MP中查看🗃️ ${val(url)}`;
const linkTMDB = (url) => `🔗在TMDB中查看🔗 ${val(url)}`;
const linkJellyfin = (url) => `🎞️在Jellyfin中查看🎞️ ${val(url)}`;
const linkHomepage = (url) => `🌐查看影视官网🌐 ${val(url)}`;
const linkPT = (url) => `🔍在PT站中查看🔍 ${val(url)}`;

// ======================= 可调参数 =======================
const BRUSHFLOW_PLUGIN_ID = "BrushFlow"; // 刷流插件 ID（插件页深链用）
const FORWARD_GENERIC_MP_NOTICE = true; // 通用 MoviePilot notice.message 是否也转发
const DROP_DUPLICATE_GENERIC_NOTICE = true; // 丢弃与已格式化事件重复的通用通知
const DROP_DUPLICATE_BRUSHFLOW_NOTICE = true; // 刷流的纯文本“种子下载”通知不再发
const FORWARD_SUBSCRIBE_MODIFIED = true; // 是否转发「真实」的订阅修改通知

// 只有这些字段变化时不推送（MoviePilot 自己维护的记账字段，兼容 v3/v2 字段名）
const MODIFY_QUIET_FIELDS = new Set([
    "last_update", "last_search", "lack_episode",
    "completed_episode", "completed_tracks", "total_episode",
    "poster", "backdrop", "backdrop_path", "vote", "description",
    "current_priority", "episode_priority",
    "current_audio_format", "current_bitrate", "current_bit_depth", "current_sample_rate",
    "execution_status", "finish_time",
    "note" // scene=progress 时只是已下载集数标记
]);
const MODIFY_SCENE_LABELS = {
    update: "手动修改订阅",
    status: "状态入口（启用/暂停/完成等）",
    reset: "重置订阅",
    agent_update: "Agent 修改",
    progress: "下载进度更新"
};
const MODIFY_FIELD_LABELS = {
    name: "名称", year: "年份", type: "类型", season: "季",
    tmdbid: "TMDB ID", doubanid: "豆瓣 ID", bangumiid: "Bangumi ID", anilistid: "AniList ID",
    media_source: "数据源", media_id: "媒体 ID",
    filter: "过滤规则", include: "包含", exclude: "排除", filter_groups: "过滤规则组",
    quality: "质量", resolution: "分辨率", effect: "特效", best_version: "洗版", best_version_full: "全集洗版",
    audio_quality: "音质", audio_format: "音频格式",
    min_bitrate: "最低码率", min_bit_depth: "最低位深", min_sample_rate: "最低采样率",
    state: "状态", note: "备注", save_path: "保存路径", downloader: "下载器",
    keyword: "关键词", sites: "站点", site: "站点",
    search_interval: "搜索间隔", search_imdbid: "IMDB 搜索",
    episode_group: "剧集组", custom_words: "自定义识别词",
    media_category: "媒体类别", media_category_id: "媒体类别 ID",
    start_season: "起始季", start_episode: "起始集", total_episode: "总集数",
    lack_episode: "缺失集数", completed_episode: "已完成集数",
    completed_tracks: "已完成曲目", total_tracks: "总曲目", episodes: "集数",
    last_update: "最后更新", last_search: "最近搜索",
    finish_time: "完成时间", date: "添加时间", username: "用户",
    poster: "海报", backdrop: "背景图", backdrop_path: "背景图",
    vote: "评分", description: "简介",
    current_priority: "当前优先级", episode_priority: "分集优先级",
    current_audio_format: "当前音频格式", current_bitrate: "当前码率",
    current_bit_depth: "当前位深", current_sample_rate: "当前采样率",
    classification_rule_id: "分类规则", classification_source: "分类来源",
    execution_status: "执行状态"
};
const STATE_LABELS = { N: "新建", R: "订阅中", P: "待定", S: "暂停", C: "已完成" };

// =======================================================

const mpUrl = (mediaType) =>
    mediaType === "电影"
        ? `${MP_BASE_URL}/#/subscribe/movie`
        : `${MP_BASE_URL}/#/subscribe/tv`;
const firstUrl = (...values) => {
    for (const value of values) {
        const s = str(value).trim();
        if (/^https?:\/\//i.test(s)) return s;
    }
    return "";
};
// 官网这一行始终输出：没有官网时用 —
const homepageLine = (mi = {}, ...extra) =>
    `\n${linkHomepage(firstUrl(mi.homepage, mi.home_page, ...extra))}`;
const siteIcon = (...values) => {
    const text = values.map(str).join(" ").toLowerCase();
    for (const [keyword, icon] of SITE_ICONS) {
        if (text.includes(keyword.toLowerCase())) return icon;
    }
    return "";
};

// 比较快照时按键名排序，避免对象 key 顺序不同造成“假差异”
const stableKey = (value) => {
    if (Array.isArray(value)) return `[${value.map(stableKey).join(",")}]`;
    if (value && typeof value === "object") {
        const keys = Object.keys(value).sort();
        return `{${keys.map((key) => `${JSON.stringify(key)}:${stableKey(value[key])}`).join(",")}}`;
    }
    return JSON.stringify(value);
};
const diffFields = (oldInfo, newInfo) => {
    const before = oldInfo || {};
    const afterInfo = newInfo || {};
    const keys = new Set([...Object.keys(before), ...Object.keys(afterInfo)]);
    return [...keys].filter((key) => stableKey(before[key]) !== stableKey(afterInfo[key])).sort();
};
const shortValue = (value, max = 140) => {
    if (value === null || value === undefined || value === "") return DASH;
    const text = typeof value === "object" ? JSON.stringify(value) : String(value);
    return text.length > max ? `${text.slice(0, max - 1)}…` : text;
};
const modifyDetail = (fields, oldInfo, newInfo) =>
    fields
        .map((field) => {
            const label = MODIFY_FIELD_LABELS[field] || field;
            const show = (info) => {
                const raw = (info || {})[field];
                if (field === "state" && raw !== undefined && raw !== null) {
                    return STATE_LABELS[raw] || str(raw);
                }
                return shortValue(raw);
            };
            return `【${label}】${show(oldInfo)} ➡️ ${show(newInfo)}`;
        })
        .join("\n");

// 解析通知文本里的“标签：值”。兼容两种写法：
//   1) MoviePilot 刷流插件：任务：xxx / 站点：xxx / 标题：xxx / 原因：xxx
//   2) 旧格式（部分通知）：【刷流站点】：xxx
const parseNoticeFields = (text) => {
    const fields = [];
    for (const line of lines(text)) {
        const bracketed = line.match(/【([^】]+)】\s*[：:]?\s*(.+)$/);
        if (bracketed) {
            const label = bracketed[1].trim();
            if (label) fields.push({ label, value: bracketed[2].trim() });
            continue;
        }
        const plain = line.match(/^([^：:]{1,12})[：:]\s*(.+)$/);
        if (plain) {
            const label = plain[1].trim();
            if (label) fields.push({ label, value: plain[2].trim() });
        }
    }
    return fields;
};
// 先按标签找，找不到再退回原来的固定行号，兼容旧格式
const noticeField = (fields, pattern, lines, index, sep = "：") => {
    const hit = fields.find((field) => pattern.test(field.label));
    if (hit) return hit.value;
    return lines[index] === undefined ? "" : after(lines[index], sep);
};
const pickField = (fields, ...patterns) => {
    for (const pattern of patterns) {
        const hit = fields.find((field) => pattern.test(field.label) && field.value);
        if (hit) return hit;
    }
    return null;
};
// 通用通知的文本没有固定格式：能识别出“标签：值”的就加【】，其它行统一加【内容】
const formatGenericText = (text) =>
    lines(text)
        .map((line) => line.trim())
        .filter(Boolean)
        .map((line) => {
            const match = line.match(/^([^：:]{1,10})[：:]\s*(.+)$/);
            return match ? `【${match[1].trim()}】${match[2].trim()}` : `【内容】${line}`;
        })
        .join("\n");

// 与已格式化事件重复的纯文本通知
const DUPLICATE_NOTICE_PATTERNS = [
    /已入库$/,
    /(已)?开始下载$/,
    /已完成订阅$/,
    /已添加订阅$/,
    /^开始订阅/,
    /订阅已(删除|修改|调整|更新|重置)$/,
    /已重置$/
];
const isDuplicateNotice = (title, text, link) => {
    const normalized = str(title).trim();
    if (DUPLICATE_NOTICE_PATTERNS.some((pattern) => pattern.test(normalized))) return true;
    const body = str(text);
    return (
        /^类型：/.test(body) &&
        /个文件/.test(body) &&
        /大小：/.test(body) &&
        str(link).includes("/history")
    );
};

const { kind, payload } = $input.first().json;
const normalizedKind = str(kind);
if (!normalizedKind.startsWith("mp-")) return [];
// 未知 MoviePilot 类型交给「无匹配来源」节点，避免重复响应
if (normalizedKind === "mp-unknown") return [];
testMode = payload.__test === true;

if (normalizedKind === "mp-subscribe") {
const data = payload.data || {};
const type = str(payload.type);
const out = [];
const add = (group, title, body, extra = {}, meta = {}) => {
    out.push({ json: { bark: bark(group, title, body, extra), ...meta } });
};

if (type === "subscribe.added") {
    const mi = data.mediainfo || {};
    const meta = (data.context && data.context.meta_info) || {};
    const title = `🆕 ${str(mi.title_year)}${meta.season_episode ? " " + str(meta.season_episode) : ""} 订阅已添加`;
    const body =
        `【评分】${score(mi.vote_average)}\n` +
        `【流行度】${val(round(mi.popularity, 2))}\n` +
        `【类别】${val(mi.category)}\n` +
        `【来自用户】${val(data.username)}\n\n` +
        `${linkMP(mpUrl(mi.type))}\n` +
        `${linkTMDB(mi.detail_link)}` +
        homepageLine(mi, data.homepage);
    add("MoviePilot", title, body, {
        icon: firstUrl(mi.logo_path, mi.poster_path) || MP_DEFAULT_ICON,
        image: firstUrl(mi.backdrop_path, mi.poster_path)
    }, { source: "MoviePilot", event: type });
    return out;
}

if (type === "subscribe.complete") {
    const mi = data.mediainfo || {};
    const si = data.subscribe_info || {};
    const duration = mediaDurationText(mi);
    const seasonText =
        str(mi.season_episode).trim() ||
        (si.season !== null && si.season !== undefined && str(si.season).trim() !== ""
            ? `S${String(si.season).padStart(2, "0")}`
            : "");
    const title = `🏁 ${str(mi.title_year)}${seasonText ? " " + seasonText : ""} 订阅已完成`;
    const body =
        `【评分】${score(mi.vote_average)}\n` +
        `【流行度】${val(round(mi.popularity, 2))}\n` +
        `【类别】${val(mi.category)}\n` +
        `【时长】${duration}\n` +
        `【来自用户】${val(si.username)}\n\n` +
        `${linkMP(mpUrl(mi.type))}\n` +
        `${linkTMDB(mi.detail_link)}` +
        homepageLine(mi, data.homepage);
    add("MoviePilot", title, body, {
        // complete 事件的 mediainfo.logo_path 经常是 null，退回海报，避免用默认图标
        icon: firstUrl(mi.logo_path, mi.poster_path, si.poster) || MP_DEFAULT_ICON,
        image: firstUrl(mi.backdrop_path, si.backdrop, mi.poster_path)
    }, { source: "MoviePilot", event: type });
    return out;
}

// subscribe.modified 有两种：真的改了订阅配置，和系统只动了记账字段的“假修改”。
// MoviePilot 事件里带 scene（update/status/reset/agent_update）和 fields（真实差异字段），
// 没有 fields 时用新旧快照自己算差异；没有任何差异就不推送。
if (type === "subscribe.modified") {
    if (!FORWARD_SUBSCRIBE_MODIFIED) {
        return fail("subscribe.modified 转发已关闭", "MoviePilot");
    }
    const si = data.subscribe_info || payload.subscribe_info || {};
    const old = data.old_subscribe_info || payload.old_subscribe_info || {};
    const scene = str(data.scene || payload.scene || "update");
    const provided = data.fields || payload.fields;
    const changed =
        Array.isArray(provided) && provided.length
            ? provided.map(str).filter(Boolean).sort()
            : diffFields(old, si);
    if (!changed.length) {
        // 新旧快照和 fields 都解析不到：可能是 MoviePilot 版本差异，
        // 保守转发一条提示，而不是静默丢掉真实的修改
        if (!Array.isArray(provided) && !Object.keys(si).length && !Object.keys(old).length) {
            add(
                "MoviePilot",
                "✏️ 订阅已修改",
                `【提示】未能从消息里解析出变更字段（可能是 MoviePilot 版本差异）\n\n` +
                    `${linkMP(mpUrl(si.type || old.type))}`,
                { icon: MP_DEFAULT_ICON, image: firstUrl(si.poster, old.poster) },
                { source: "MoviePilot", event: type, scene }
            );
            return out;
        }
        return fail("subscribe.modified 没有实际字段变化（no-op）", "MoviePilot");
    }
    const meaningful = changed.filter((field) => !MODIFY_QUIET_FIELDS.has(field));
    if (!meaningful.length) {
        return fail(`subscribe.modified 仅有系统字段变化：${changed.join("、")}`, "MoviePilot");
    }
    const name = str(si.name) || str(old.name) || "未知订阅";
    const body =
        `【场景】${val(MODIFY_SCENE_LABELS[scene] || scene)}\n` +
        (si.username ? `【来自用户】${val(si.username)}\n` : "") +
        `【修改内容】\n${modifyDetail(meaningful, old, si)}\n\n` +
        `${linkMP(mpUrl(si.type || old.type))}`;
    add("MoviePilot", `✏️ ${name} 订阅已修改`, body, {
        icon: MP_DEFAULT_ICON,
        image: firstUrl(si.poster, old.poster)
    }, { source: "MoviePilot", event: type, scene, fields: meaningful });
    return out;
}

if (type === "subscribe.deleted") {
    const si = data.subscribe_info || {};
    const title = `🚫 ${str(si.name)} 订阅已删除`;
    const body = `【状态】已删除\n\n${linkMP(mpUrl(si.type))}`;
    add("MoviePilot", title, body, {
        icon: MP_DEFAULT_ICON,
        image: firstUrl(si.poster)
    }, { source: "MoviePilot", event: type });
    return out;
}

return fail(`无匹配的 MoviePilot 订阅事件类型：${type || "(空)"}`, "MoviePilot");
}

if (normalizedKind === "mp-download") {
const data = payload.data || {};
const type = str(payload.type);

if (type === "download.added") {
    const ctx = data.context || {};
    const mi = ctx.media_info || {};
    const meta = ctx.meta_info || {};
    const torrent = ctx.torrent_info || {};
    const labels = Array.isArray(torrent.labels) ? torrent.labels : [];
    const title = `⬇️ ${str(mi.title_year)}${meta.season_episode ? " " + str(meta.season_episode) : ""} 已开始下载`;
    const bodyLines = [
        `【站点】${val(torrent.site_name)}`,
        `【下载器】${val(data.downloader)}`,
        `【来自用户】${val(data.username)}`,
        `【质量】${val(`${str(meta.resource_pix)} ${str(meta.resource_type)}`)}`,
        `【编码格式】${val(`${str(meta.video_encode)} ${str(meta.audio_encode)}`)}`,
        `【大小】${formatSize(torrent.size)}`,
        `【做种数】${val(torrent.seeders)}`,
        `【相关种子】${val(torrent.title)}`,
        `【种子发布日期】${val(torrent.pubdate)}`,
        `【描述】${val(torrent.description)}`
    ];
    if (mi.last_air_date != null) bodyLines.push(`【上次有新集释出】${val(mi.last_air_date)}`);
    if (labels.length) bodyLines.push(`【标签】${val(labels.join("·"))}`);
    const body =
        bodyLines.join("\n") +
        `\n\n${linkMP(mpUrl(mi.type))}\n` +
        `${linkTMDB(mi.detail_link)}` +
        homepageLine(mi, data.homepage);
    return [
        {
            json: {
                bark: bark("MoviePilot", title, body, {
                    icon: siteIcon(torrent.site_name) || MP_DEFAULT_ICON,
                    image: firstUrl(mi.backdrop_path, mi.poster_path)
                }),
                source: "MoviePilot",
                event: type
            }
        }
    ];
}

if (type === "transfer.complete") {
    const mi = data.mediainfo || {};
    const meta = data.meta || {};
    const transfer = data.transferinfo || {};
    const duration = mediaDurationText(mi);

    let transferPath = "";
    if (transfer.success) {
        const fileitem = transfer.fileitem || {};
        const target = transfer.target_diritem || {};
        const filePath = str(fileitem.path);
        const fileName = str(fileitem.name);
        const dir =
            fileName && filePath.includes(fileName)
                ? filePath.slice(0, filePath.indexOf(fileName))
                : filePath;
        transferPath = `[ "${dir}" ➡️ "${str(target.path)}" ]`;
    }

    const seasonEpisode = str(meta.season_episode);
    const jellyfinUrl = mi.type === "电影" ? JELLYFIN_MOVIES : JELLYFIN_TV;
    const title = transfer.success
        ? `🎬 ${str(mi.title_year)}${seasonEpisode ? " " + seasonEpisode : ""} 已入库`
        : `❌ ${str(mi.title_year)}${seasonEpisode ? " " + seasonEpisode : ""} 入库失败`;
    const transferLines = [];
    if (transfer.success) {
        transferLines.push(`【文件数】${val(transfer.file_count)} 个`);
        transferLines.push(`【大小】${formatSize(transfer.total_size)}`);
        transferLines.push(`【转移路径】${transferPath}`);
    } else {
        transferLines.push("【状态】转移失败");
    }
    const body =
        `【评分】${score(mi.vote_average)}\n` +
        `【流行度】${val(round(mi.popularity, 2))}\n` +
        `【类别】${val(mi.category)}\n` +
        `【时长】${duration}\n` +
        `【质量】${val(`${str(meta.resource_pix)} ${str(meta.resource_type)}`)}\n` +
        `【编码格式】${val(`${str(meta.video_encode)} ${str(meta.audio_encode)}`)}\n` +
        `${transferLines.join("\n")}\n\n` +
        `${linkJellyfin(jellyfinUrl)}\n` +
        `${linkTMDB(mi.detail_link)}\n` +
        `${linkHomepage(mi.homepage)}`;

    // 入库事件的结构化信息，供聚合使用（支持单集和多集范围如 S01 E01-E02，电影无季集不聚合）
    const seasonMatch = seasonEpisode.match(/S(\d+)/i);
    const seasonNum = seasonMatch ? Number(seasonMatch[1]) : Number(meta.begin_season);
    const parsedEpisodes = [];
    if (Array.isArray(meta.episode_list) && meta.episode_list.length) {
        for (const ep of meta.episode_list) {
            const n = Number(ep);
            if (Number.isInteger(n) && n > 0) parsedEpisodes.push(n);
        }
    }
    if (!parsedEpisodes.length) {
        const rangeMatch = seasonEpisode.match(/E(\d+)\s*-\s*E?(\d+)/i);
        if (rangeMatch) {
            const startEp = Number(rangeMatch[1]);
            const endEp = Number(rangeMatch[2]);
            if (startEp > 0 && endEp >= startEp && endEp - startEp <= 500) {
                for (let ep = startEp; ep <= endEp; ep++) parsedEpisodes.push(ep);
            }
        } else {
            for (const m of seasonEpisode.matchAll(/E(\d+)/gi)) {
                const n = Number(m[1]);
                if (n > 0) parsedEpisodes.push(n);
            }
        }
    }
    const uniqueEpList = [...new Set(parsedEpisodes)].sort((a, b) => a - b);
    const mediaImage = firstUrl(mi.backdrop_path, mi.poster_path);
    const transferMeta =
        transfer.success && Number.isInteger(seasonNum) && seasonNum >= 0 && uniqueEpList.length
            ? {
                  kind: "episode",
                  show: str(mi.title_year),
                  season: seasonNum,
                  episode: uniqueEpList[0],
                  episodes: uniqueEpList,
                  score: str(mi.vote_average),
                  quality: `${str(meta.resource_pix)} ${str(meta.resource_type)}`.trim(),
                  duration,
                  popularity: round(mi.popularity, 2),
                  category: str(mi.category),
                  encode: `${str(meta.video_encode)} ${str(meta.audio_encode)}`.trim(),
                  size: num(transfer.total_size),
                  fileCount: num(transfer.file_count),
                  detailLink: str(mi.detail_link),
                  homepage: str(mi.homepage),
                  jellyfinUrl,
                  icon: firstUrl(mi.logo_path, mi.poster_path) || MP_DEFAULT_ICON,
                  image: mediaImage
              }
            : null;

    return [
        {
            json: {
                bark: bark("MoviePilot", title, body, {
                    icon: firstUrl(mi.logo_path, mi.poster_path) || MP_DEFAULT_ICON,
                    image: mediaImage
                }),
                source: "MoviePilot",
                event: type,
                transfer: transferMeta
            }
        }
    ];
}

return fail(`无匹配的 MoviePilot 下载事件类型：${type || "(空)"}`, "MoviePilot");
}

if (normalizedKind === "mp-plugin") {
const data = payload.data || {};
const d = data.data || {};
const siteName = str(d.site_name);
const eventName = str(data.event_name);
const isBrushFlow = eventName.startsWith("brushflow");
const title = eventName === "brushflow_download_added" ? "🖌️ 刷流任务已添加" : `🖌️ ${eventName}`;
const pluginUrl = `${MP_BASE_URL}/#/plugins?id=${encodeURIComponent(
    str(data.plugin_id) || BRUSHFLOW_PLUGIN_ID
)}`;
const body =
    `【站点】${val(siteName)}\n` +
    `【下载器】${val(data.downloader)}\n` +
    `【大小】${formatSize(d.size)}\n` +
    `【相关种子】${val([str(d.title).trim(), str(d.description).trim()].filter(Boolean).join(" | "))}\n` +
    `【种子发布日期】${val(d.pubdate)}\n\n` +
    (isBrushFlow ? `${linkMP(pluginUrl)}\n` : "") +
    `${linkPT(d.page_url)}`;

return [
    {
        json: {
            bark: bark(isBrushFlow ? "MoviePilot刷流" : "MoviePilot", title, body, {
                icon: siteIcon(siteName) || MP_DEFAULT_ICON
            }),
            source: "MoviePilot",
            event: "plugin.triggered"
        }
    }
];
}

if (normalizedKind === "mp-notice") {
const d = payload.data || {};
const rawTitle = str(d.title);
const textLines = lines(d.text);
const fields = parseNoticeFields(d.text);
const icon = str(d.link).includes("AutoSports")
    ? SPORTS_ICON
    : siteIcon(rawTitle, textLines[0] || "", textLines[1] || "") || MP_DEFAULT_ICON;
const noticeImage = firstUrl(d.image, d.poster);

if (rawTitle.includes("刷流")) {
    // “刷流任务种子下载”与 plugin.triggered 的自定义格式重复，只保留后者
    if (rawTitle.includes("种子下载") && DROP_DUPLICATE_BRUSHFLOW_NOTICE) {
        return fail(`刷流下载通知改用 plugin.triggered 格式，忽略重复：${rawTitle}`, "MoviePilot");
    }
    const siteField = pickField(fields, /^刷流站点$/, /^站点$/, /^任务$/);
    const site = siteField ? siteField.value : "";
    const usable = (field) => Boolean(field && field.value && !(site && field.value === site));
    // “相关种子”直接填种子名：标题 / 种子名 / 种子名称 / 种子标题 / 种子 / 相关种子 / 种子描述 / 种子体积
    const seedField =
        [
            /^标题$/,
            /^种子名称$/,
            /^种子名$/,
            /^种子标题$/,
            /^种子$/,
            /相关种子/,
            /种子(描述|信息)/,
            /种子体积/
        ]
            .map((pattern) => fields.find((field) => pattern.test(field.label) && usable(field)))
            .find(Boolean) || null;
    const seed = seedField ? seedField.value : "";
    const reasonField = pickField(fields, /^原因$/, /变动原因/);
    const sizeField = pickField(fields, /^大小$/, /^体积$/, /种子体积/);
    const bodyLines = [];
    if (site) bodyLines.push(`【刷流站点】${val(site)}`);
    if (seed) bodyLines.push(`【相关种子】${val(seed)}`);
    if (reasonField) {
        const label = reasonField.label.includes("变动") ? "变动原因" : "原因";
        bodyLines.push(`【${label}】${val(reasonField.value)}`);
    }
    if (sizeField && sizeField !== seedField) bodyLines.push(`【大小】${val(sizeField.value)}`);
    bodyLines.push(`\n${linkMP(`${MP_BASE_URL}/#/plugins?id=${encodeURIComponent(BRUSHFLOW_PLUGIN_ID)}`)}`);
    return [
        {
            json: {
                bark: bark(
                    "MoviePilot刷流",
                    `🧹 ${rawTitle.includes("删除") ? "刷流任务已删除" : rawTitle.replace(/【/g, "").replace(/】/g, "")}`,
                    bodyLines.join("\n"),
                    { icon, image: noticeImage }
                ),
                source: "MoviePilot",
                event: "notice.brushflow"
            }
        }
    ];
}

if (rawTitle.includes("体育比赛")) {
    const seedMatch = rawTitle.match(/【([^】]+)】/);
    const seed = seedMatch ? seedMatch[1] : "";
    const body =
        `【赛事】${val(noticeField(fields, /赛事/, textLines, 0))}\n` +
        `【轮次】${val(noticeField(fields, /轮次/, textLines, 1, ": "))}\n` +
        `【对阵】${val(noticeField(fields, /对阵/, textLines, 2, ": "))}\n` +
        (rawTitle.includes("种子") ? `【种子】${val(seed)}\n` : "") +
        `\n${linkJellyfin(JELLYFIN_SPORTS)}`;
    return [
        {
            json: {
                bark: bark(
                    "MoviePilot体育",
                    rawTitle.includes("已开始下载") ? "🏆 体育比赛种子开始下载" : "🏆 体育比赛已入库",
                    body,
                    { icon, image: noticeImage }
                ),
                source: "MoviePilot",
                event: "notice.sports"
            }
        }
    ];
}

if (/站点.*(?:消息|私信)/.test(rawTitle)) {
    const siteMatch = rawTitle.match(/站点\s*[：:]?\s*(.+?)\s*(?:有新)?(?:消息|私信)/);
    const siteField = pickField(fields, /^站点$/);
    const site =
        (siteMatch && siteMatch[1].replace(/[【】\[\]]/g, "").trim()) ||
        (siteField && siteField.value) ||
        str(rawTitle).split(" ")[1] ||
        "";
    const msgTitle = noticeField(fields, /标题/, textLines, 1);
    const msgTime = noticeField(fields, /时间/, textLines, 0);
    // 站点私信正文常为“内容：\n多行内容”，完整保留所有行，并去掉与标题重复的前缀
    const contentIdx = textLines.findIndex((line) => /^内容\s*[：:]/.test(line.trim()));
    let msgContent = "";
    if (contentIdx !== -1) {
        const firstLine = textLines[contentIdx].replace(/^\s*内容\s*[：:]\s*/, "").trim();
        const restLines = textLines.slice(contentIdx + 1).map((line) => line.trim()).filter(Boolean);
        msgContent = [firstLine, ...restLines].filter(Boolean).join("\n").trim();
    } else {
        msgContent = noticeField(fields, /内容/, textLines, 3);
    }
    if (msgTitle && msgContent) {
        const escapedTitle = msgTitle.replace(/[.*+?^$()|[\]\\]/g, "\\$&");
        const prefixRe = new RegExp(`^${escapedTitle}\\s*[：:]\\s*`);
        msgContent = msgContent.replace(prefixRe, "").trim() || msgContent;
    }
    const title = site ? `✉️ 站点 ${site} 有新私信` : "✉️ 站点有新私信";
    const body =
        `【站点】${val(site)}\n` +
        `【标题】${val(msgTitle)}\n` +
        `【内容】${val(msgContent)}\n` +
        `【时间】${val(msgTime)}\n\n` +
        `${linkPT(d.link)}`;
    return [
        {
            json: {
                bark: bark("MoviePilot站点", title, body, { icon, image: noticeImage }),
                source: "MoviePilot",
                event: "notice.site"
            }
        }
    ];
}

if (DROP_DUPLICATE_GENERIC_NOTICE && isDuplicateNotice(rawTitle, d.text, d.link)) {
    return fail(`通用通知与已格式化事件重复，已忽略：${rawTitle}`, "MoviePilot");
}

if (FORWARD_GENERIC_MP_NOTICE) {
    const group = d.mtype && d.mtype._value_ === "站点" ? "MoviePilot站点" : "MoviePilot";
    let body = formatGenericText(d.text);
    if (d.link) body += `\n\n${linkMP(d.link)}`;
    return [
        {
            json: {
                bark: bark(group, `📢 ${rawTitle || "MoviePilot 通知"}`, body, { icon, image: noticeImage }),
                source: "MoviePilot",
                event: "notice.generic"
            }
        }
    ];
}

return fail("无匹配的 MoviePilot notice.message 类型", "MoviePilot");
}

return fail(`无匹配的 MoviePilot 事件类型：${str(payload.type) || "(空)"}`, "MoviePilot");
